/**
 * ============================================================================
 * 視覺藝術作品署名與靈感宣告 (ATTRIBUTION & INSPIRATION DECLARATION)
 * ============================================================================
 * 作者 (Author / Code Adaptor): Uncler M
 * 靈感啟發來源 (Inspired By): 來自星星的藝術家 - "代码练习/ No.4 春水 - 附源代码"
 * 原始作品討論 (Original Note): http://xhslink.com/o/3T3Ia3iMcRv
 * 授權協議 (License): Creative Commons Attribution-NonCommercial-ShareAlike 4.0 (CC BY-NC-SA 4.0)
 * 
 * [說明 / Notice]
 * 本作品由 Uncler M 編寫與視聽化對應。演算法靈感取材自「來自星星的藝術家」創作之
 * 「春水幾何波浪疊加、水滴投石漣漪動態海報」視覺概念。
 * 專為 4K MV Visual Integration Editor 專案打造。
 * ============================================================================
 */

let NUM_WAVES = 22;
let wavePhase = 0;
let ripples = [];

let smoothedSubBass = 0.0;
let smoothedPercussive = 0.0;
let smoothedMid = 0.0;

setup = () => {
  p5.disableFriendlyErrors = true;
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 1.0);
};

draw = () => {
  // 1. 動態音訊信號平滑處理
  let rawSubBass = (typeof sub_bass !== 'undefined') ? sub_bass : (typeof sub_bass_ratio !== 'undefined' ? sub_bass_ratio : (mouseIsPressed ? 0.85 : 0.22));
  let rawPercussive = (typeof percussive !== 'undefined') ? percussive : (mouseIsPressed ? 0.9 : 0.1);
  let rawMid = (typeof mid !== 'undefined') ? mid : (typeof mid_ratio !== 'undefined' ? mid_ratio : 0.3);

  smoothedSubBass += (rawSubBass - smoothedSubBass) * 0.14;
  smoothedPercussive += (rawPercussive - smoothedPercussive) * 0.28;
  smoothedMid += (rawMid - smoothedMid) * 0.18;

  wavePhase += 0.015 + smoothedMid * 0.03;

  // 2. 春水淡雅背景
  background(205, 30, 8, 0.25);

  let currentHue = (typeof chord_hue !== 'undefined' && chord_hue > 0) ? chord_hue : 190;

  // 3. 重拍觸發「水滴投石漣漪 (Droplet Ripple Impact)」
  if (smoothedPercussive > 0.65 && random() < 0.25) {
    ripples.push({
      x: random(width * 0.1, width * 0.9),
      y: random(height * 0.2, height * 0.8),
      r: 5.0,
      maxR: random(150, 320),
      strength: smoothedPercussive * 45.0,
      hue: (currentHue + random(-30, 30)) % 360
    });
  }

  // 4. 更新水滴漣漪佇列
  for (let i = ripples.length - 1; i >= 0; i--) {
    let rp = ripples[i];
    rp.r += 4.5 + smoothedSubBass * 6.0;
    rp.strength *= 0.94;

    if (rp.r > rp.maxR || rp.strength < 0.5) {
      ripples.splice(i, 1);
    }
  }

  // 5. 繪製水滴同心圓擴散漣漪
  noFill();
  for (let i = 0; i < ripples.length; i++) {
    let rp = ripples[i];
    let alpha = map(rp.r, 0, rp.maxR, 0.8, 0.0);
    stroke(rp.hue, 75, 95, alpha);
    strokeWeight(1.2 + (rp.strength / 45.0) * 3.0);
    ellipse(rp.x, rp.y, rp.r * 2.0, rp.r * 1.2); // 微橢圓水面透視
  }

  // 6. 繪製層次春水幾何波浪曲線 (Spring Water Wave Ribbons)
  let layerHeight = height / (NUM_WAVES - 2);

  for (let k = 0; k < NUM_WAVES; k++) {
    let baseY = k * layerHeight - 30;
    let waveHue = (currentHue + k * 4.0) % 360;
    let layerAlpha = map(k, 0, NUM_WAVES, 0.4, 0.85);

    fill(waveHue, 65, 85, layerAlpha * 0.25);
    stroke(waveHue, 80, 95, layerAlpha);
    strokeWeight(1.0 + smoothedSubBass * 2.5);

    beginShape();
    vertex(0, height + 50);

    for (let x = 0; x <= width + 20; x += 20) {
      // 複合正弦波疊加
      let sineVal = sin(x * 0.006 + wavePhase + k * 0.3) * (30.0 + smoothedSubBass * 60.0);
      let cosVal = cos(x * 0.012 - wavePhase * 1.5 + k * 0.5) * (15.0 + smoothedMid * 30.0);
      let noiseVal = (noise(x * 0.004, k * 0.1, wavePhase * 0.5) - 0.5) * 45.0 * smoothedMid;

      let yOffset = sineVal + cosVal + noiseVal;

      // 加上水滴漣漪垂直擾動 (Droplet Ripple Wave Deformation)
      for (let r = 0; r < ripples.length; r++) {
        let rp = ripples[r];
        let d = dist(x, baseY + yOffset, rp.x, rp.y);
        if (abs(d - rp.r) < 40) {
          let rippleWave = sin((d - rp.r) * 0.15) * rp.strength * (1.0 - abs(d - rp.r) / 40);
          yOffset += rippleWave;
        }
      }

      vertex(x, baseY + yOffset);
    }

    vertex(width + 50, height + 50);
    endShape(CLOSE);
  }
};

// === 運行時防崩潰護欄與 DOM 代理 Stubs ===
if (typeof createP === 'undefined') window.createP = function() { return { position: function(){}, style: function(){} }; };
